package com.governai.regulatory; import com.governai.policy.DocumentStatus; import tools.jackson.databind.JsonNode; import java.time.*; import java.util.UUID; public record RegulatoryDocumentResponse(UUID id,String title,String documentCode,String jurisdiction,String authority,String category,String version,DocumentStatus status,LocalDate effectiveDate,String sourceUrl,JsonNode metadata,OffsetDateTime createdAt,OffsetDateTime updatedAt){ static RegulatoryDocumentResponse from(RegulatoryDocument d){return new RegulatoryDocumentResponse(d.getId(),d.getTitle(),d.getDocumentCode(),d.getJurisdiction(),d.getAuthority(),d.getCategory(),d.getVersion(),d.getStatus(),d.getEffectiveDate(),d.getSourceUrl(),d.getMetadata(),d.getCreatedAt(),d.getUpdatedAt());}}
